14	  pictureSource?: PictureSource;
15	  lastLoginAt?: string;
16	  // Original Logto subject identifier, preserved for debugging/auditing.
17	  logtoId?: string;
18	  /**
19	   * Set when the id_token session is valid but the backend enrichment call
20	   * (GET /api/auth/me with `Authorization: Bearer <access_token>`) was
21	   * rejected — i.e. `4xx` (typically `401` because the audience or JWKS
22	   * wiring is wrong). Surfaced in the navbar dropdown so users can tell
23	   * apart "logged out" from "logged in but the backend doesn't accept me".
24	   * Transient failures (5xx / network blip) are intentionally not flagged —
25	   * returning the id_token-only user without this property keeps the session
26	   * visually stable during a brief outage.
