1	"use server";
2	import { updateTag, refresh } from "next/cache";
3	import { after } from "next/server";
4	import { captureException } from "@sentry/nextjs";
5	import { createEvent } from "@lib/api/events";
6	import type { E2EEventExtras } from "types/api/event";
7	import type { EventCreateRequestDTO } from "types/api/event";
8	import { eventsTag, eventsCategorizedTag } from "@lib/cache/tags";
9	import { fireAndForgetFetch } from "@utils/safe-fetch";
10	import { env } from "@utils/misc-helpers";
11	
12	/**
13	 * Sends email notification via Pipedream when a new event is published.
14	 * Only runs in production environment with configured webhook URL.
15	 * Failures are logged but don't block event creation.
16	 */
17	async function sendNewEventEmail(title: string, slug: string): Promise<void> {
18	  const webhookUrl = process.env.NEW_EVENT_EMAIL_URL;
19	  const isProduction = env === "prod";
20	
21	  if (!webhookUrl || !isProduction) {
22	    return;
23	  }
24	
25	  await fireAndForgetFetch(webhookUrl, {
26	    method: "POST",
27	    headers: {
28	      Accept: "application/json",
29	      "Content-Type": "application/json",
30	    },
31	    body: JSON.stringify({ title, slug }),
32	    context: {
33	      tags: { section: "publica", action: "send-email" },
34	      extra: { title, slug },
35	    },
36	  });
37	}
38	
39	export async function createEventAction(
40	  data: EventCreateRequestDTO,
41	  e2eExtras?: E2EEventExtras
42	) {
43	  // 2026-07-26 round-5: catch the mutation error path so we can distinguish
44	  // 401 (likely stale Bearer — user should log out and back in) from 403
45	  // (profileCompleted: false per backend spec — user should complete
46	  // onboarding). Anything else is a real 5xx and rethrows. We log + tag
47	  // Sentry with the next action so the form can render the right message.
48	  let created;
49	  try {
50	    // 1. Create the event in your backend
51	    created = await createEvent(data, e2eExtras);
52	  } catch (err) {
53	    const status = (err as { status?: number })?.status;
54	    if (status === 401 || status === 403) {
55	      const nextAction =
56	        status === 401 ? "logout-and-relogin" : "complete-profile";
57	      console.error(
58	        `createEventAction: backend rejected with ${status} \u2014 ${status === 401 ? "Likely stale Bearer \u2014 user should log out and back in." : "Likely profileCompleted: false \u2014 user should complete profile onboarding."}`,
59	      );
60	      captureException(err, {
61	        tags: {
62	          section: "publica-create",
63	          authStatus: String(status),
64	          nextAction,
65	        },
66	        // Send only field names + truncated title to avoid leaking content.
67	        extra: {
68	          dataFields: Object.keys(data ?? {}),
69	          titleHint: data?.title?.slice(0, 40),
70	        },
71	      });
72	    }
73	    throw err;
74	  }
75	
76	  // 2. Send email notification (fire-and-forget, non-blocking)
77	  // Uses `after` to ensure execution completes in serverless environments
78	  if (created?.slug && created?.title) {
79	    const { title, slug } = created;
80	    after(() => sendNewEventEmail(title, slug));
81	  }
82	
83	  // 3. Immediately expire cache tags for event lists and categorized collections
84	  // This ensures read-your-own-writes: the new event appears immediately
85	  updateTag(eventsTag);
86	  updateTag(eventsCategorizedTag);
87	  // Refresh the current request to reflect changes
88	  refresh();
89	
90	  // 4. Return the created event or result for your client
91	  return { success: true, event: created };
92	}
