1	import { NextResponse, type NextRequest } from "next/server";
2	import { getAccessTokenFromCookies } from "@utils/auth-cookies";
3	import { patchMeProfileExternal } from "@lib/api/users-external";
4	import { handleApiError } from "@utils/api-error-handler";
5	import { profileUpdateSchema } from "lib/validation/auth";
6	import type { ProfileUpdateRequestDTO } from "types/api/user";
7	
8	const NO_STORE = { "Cache-Control": "no-store" } as const;
9	
10	const BAD_REQUEST = (message: string) =>
11	  NextResponse.json({ error: message }, { status: 400, headers: NO_STORE });
12	
13	// PATCH /api/users/me/profile — edit the signed-in user's profile fields
14	// (username, displayName, bio). Backend returns 400 (invalid format),
15	// 409 (collision: username taken), or 403 (no session). The route delegates
16	// auth via the HttpOnly `auth_token` cookie read here (same origin as the
17	// page) and forwards it as a Bearer header to the backend.
18	//
19	// Onboarding completion is signaled by `profileCompleted: true` returning from
20	// /api/auth/me on the next GET — the operator's only job is to keep that
21	// cookie user fresh.
22	export async function PATCH(request: NextRequest): Promise<Response> {
23	  const accessToken = await getAccessTokenFromCookies();
24	  if (!accessToken) {
25	    return NextResponse.json(
26	      { error: "Authentication required" },
27	      { status: 401, headers: NO_STORE },
28	    );
29	  }
30	
31	  // Defense-in-depth: re-validate the payload shape on the server. The
32	  // client also validates (live feedback) but a bot/curl hitting the route
33	  // with garbage should 400 here without ever reaching the backend.
34	  let body: ProfileUpdateRequestDTO;
35	  try {
36	    const json: unknown = await request.json();
37	    const parsed = profileUpdateSchema.safeParse(json);
38	    if (!parsed.success) {
39	      const first = parsed.error.issues[0]?.message ?? "Invalid payload";
40	      return BAD_REQUEST(first);
41	    }
42	    body = parsed.data;
43	  } catch {
44	    return BAD_REQUEST("Invalid JSON body");
45	  }
46	
47	  try {
48	    const updated = await patchMeProfileExternal(body, accessToken);
49	    if (!updated) {
50	      return NextResponse.json(
51	        { error: "Profile update failed" },
52	        { status: 502, headers: NO_STORE },
53	      );
54	    }
55	    return NextResponse.json(updated, { status: 200, headers: NO_STORE });
56	  } catch (e) {
57	    return handleApiError(e, "/api/users/me/profile", {
58	      fallbackData: null,
59	    });
60	  }
61	}
