10	// No generateStaticParams — usernames are user-generated with infinite
11	// cardinality. Pages render on first request and are cached automatically.
12	
13	export async function generateMetadata({
14	  params,
15	}: {
16	  params: Promise<{ username: string }>;
17	}) {
18	  const { username } = await params;
19	  const [profile, locale, t] = await Promise.all([
20	    getUserByUsernameCached(username),
21	    getLocaleSafely(),
22	    getTranslations("Components.Profile"),
23	  ]);
24	
25	  if (!profile) {
26	    return { title: "Not Found" };
27	  }
28	
29	  // 2026-07-25 backend moved to `displayName`; keep `name` as a fallback
30	  // during the cut-over window so SEO titles don't render as "undefined".
31	  const displayName =
32	    profile.displayName?.trim() || profile.name?.trim() || profile.username;
33	  const title = t("title", { name: displayName });
34	  const description = t("metaDescription", { name: displayName });
35	  const canonical = toLocalizedUrl(`/perfil/${username}`, locale);
36	
37	  return buildPageMeta({
38	    title,
39	    description,
40	    canonical,
41	    image: `${siteUrl}/static/images/logo-seo-meta.webp`,
42	    locale,
43	    openGraphType: "profile",
44	  });
45	}
