1	import { NextResponse, type NextRequest } from "next/server";
2	import { getAccessTokenFromCookies } from "@utils/auth-cookies";
3	import {
4	  deleteUserAvatarExternal,
5	  uploadUserAvatarExternal,
6	} from "@lib/api/users-external";
7	import { handleApiError } from "@utils/api-error-handler";
8	
9	const NO_STORE = { "Cache-Control": "no-store" } as const;
10	
11	const MAX_AVATAR_BYTES = 2 * 1024 * 1024; // 2 MB hard cap; matches MAX_TOTAL_UPLOAD_BYTES
12	const ALLOWED_AVATAR_TYPES = new Set([
13	  "image/jpeg",
14	  "image/png",
15	  "image/jpg",
16	  "image/webp",
17	]);
18	
19	async function requireAuthCookie(): Promise<
20	  { ok: true; token: string } | { ok: false; response: Response }
21	> {
22	  const token = await getAccessTokenFromCookies();
23	  if (!token) {
24	    return {
25	      ok: false,
26	      response: NextResponse.json(
27	        { error: "Authentication required" },
28	        { status: 401, headers: NO_STORE },
29	      ),
30	    };
31	  }
32	  return { ok: true, token };
33	}
34	
35	// POST /api/users/me/avatar — multipart upload with field `avatarFile`.
36	// Returns { avatarUrl: string } per backend handoff. Same auth model as
37	// profile: HttpOnly cookie → Bearer. The external wrapper handles the
38	// backend auth + HMAC layer.
39	export async function POST(request: NextRequest): Promise<Response> {
40	  const auth = await requireAuthCookie();
41	  if (!auth.ok) return auth.response;
42	
43	  // Defense-in-depth size guard (three layers):
44	  //   1. Reject Transfer-Encoding: chunked + require a well-formed
45	  //      Content-Length so signatures on Content-Length actually constrain
46	  //      the body. Without these, an attacker can stream chunks up to the
47	  //      upstream proxy's max (Cloudflare free tier = 100 MB) and force
48	  //      formData() to buffer it all before our file.size check runs.
49	  //   2. Content-Length upper bound (cheap, rejects obviously oversized
50	  //      requests before the multipart parser is invoked).
51	  //   3. file.size post-check after parsing (binding — catches clients that
52	  //      spoof Content-Length while obeying the framing rules: the only
53	  //      honest over-limit case is a client that's interleaved framing
54	  //      tricks with a body larger than declared).
55	  //
56	  // TODO(ops): pair this with a Cloudflare "Max Upload Size" zone setting
57	  // (suggested 25 MB) so even chunked/stale-framed requests stop at the
58	  // edge and never reach Traefik/Coolify bandwidth. See docs/incidents
59	  // search: "body-size" for related context. Until that is configured,
60	  // layer 1 below is the only thing standing between an attacker and the
61	  // Node multipart parser.
62	  const transferEncoding = (
63	    request.headers.get("transfer-encoding") ?? ""
64	  ).toLowerCase();
65	  if (transferEncoding.includes("chunked")) {
66	    return NextResponse.json(
67	      { error: "Chunked transfer encoding is not supported" },
68	      { status: 411, headers: NO_STORE },
69	    );
70	  }
71	  const rawContentLength = request.headers.get("content-length");
72	  if (!rawContentLength) {
73	    return NextResponse.json(
74	      { error: "Content-Length header is required" },
75	      { status: 411, headers: NO_STORE },
76	    );
77	  }
78	  const contentLengthHeader = Number(rawContentLength);
79	  // +8192 envelope allowance: a multipart body needs ~200–400 bytes of
80	  // boundary + part headers + CRLFs around the file bytes. Without this, a
81	  // legitimate 2 MB file produces Content-Length ≈ 2.0003 MB and would 413
82	  // here even though the file.size post-check below would have allowed it.
83	  // The 8 KB slack is well under the Cloudflare free-tier 100 MB ceiling
84	  // (see the TODO(ops) note above) and gives the file-size postcheck the
85	  // final say on the actual payload. PR review thread 121V was the trigger.
86	  const MAX_AVATAR_REQUEST_BYTES = MAX_AVATAR_BYTES + 8192;
87	  if (
88	    !Number.isFinite(contentLengthHeader) ||
89	    contentLengthHeader < 0 ||
90	    contentLengthHeader > MAX_AVATAR_REQUEST_BYTES
91	  ) {
92	    return NextResponse.json(
93	      { error: "Avatar too large (max 2 MB)" },
94	      { status: 413, headers: NO_STORE },
95	    );
96	  }
97	  // Require a well-formed multipart Content-Type with a boundary parameter;
98	  // an empty / malformed request that bypasses the multipart parser would
99	  // otherwise fall through to formData() and surface as a generic 400.
100	  const declaredContentType = (request.headers.get("content-type") ?? "").toLowerCase();
101	  if (
102	    !declaredContentType.startsWith("multipart/form-data") ||
103	    !declaredContentType.includes("boundary=")
104	  ) {
105	    return NextResponse.json(
106	      { error: "Expected multipart/form-data with a boundary" },
107	      { status: 415, headers: NO_STORE },
108	    );
109	  }
110	
111	  let form: FormData;
112	  try {
113	    form = await request.formData();
114	  } catch {
115	    return NextResponse.json(
116	      { error: "Invalid form data" },
117	      { status: 400, headers: NO_STORE },
118	    );
119	  }
120	  const file = form.get("avatarFile");
121	  if (!(file instanceof File)) {
122	    return NextResponse.json(
123	      { error: "Missing 'avatarFile' field" },
124	      { status: 400, headers: NO_STORE },
125	    );
126	  }
127	  if (file.size > MAX_AVATAR_BYTES) {
128	    return NextResponse.json(
129	      { error: "Avatar too large (max 2 MB)" },
130	      { status: 413, headers: NO_STORE },
131	    );
132	  }
133	  if (!file.type || !ALLOWED_AVATAR_TYPES.has(file.type)) {
134	    return NextResponse.json(
135	      { error: "Unsupported avatar format" },
136	      { status: 415, headers: NO_STORE },
137	    );
138	  }
139	
140	  try {
141	    const result = await uploadUserAvatarExternal(file, auth.token);
142	    if (!result) {
143	      return NextResponse.json(
144	        { error: "Avatar upload failed" },
145	        { status: 502, headers: NO_STORE },
146	      );
147	    }
148	    return NextResponse.json(result, { status: 200, headers: NO_STORE });
149	  } catch (e) {
150	    return handleApiError(e, "/api/users/me/avatar", {
151	      fallbackData: null,
152	    });
153	  }
154	}
155	
156	// DELETE /api/users/me/avatar — clear the signed-in user's avatar.
157	export async function DELETE(_request: NextRequest): Promise<Response> {
158	  const auth = await requireAuthCookie();
159	  if (!auth.ok) return auth.response;
160	
161	  try {
162	    const result = await deleteUserAvatarExternal(auth.token);
163	    return NextResponse.json(
164	      { ok: result },
165	      { status: result ? 200 : 502, headers: NO_STORE },
166	    );
167	  } catch (e) {
168	    return handleApiError(e, "/api/users/me/avatar", {
169	      fallbackData: null,
170	    });
171	  }
172	}
