18	/**
19	 * Authenticated session profile: GET /api/auth/me. Backend-owned fields
20	 * (avatarUrl/pictureSource/role/lastLoginAt) that the Logto id_token can't
21	 * carry — the id_token has no concept of an in-app avatar upload or login
22	 * audit trail.
23	 *
24	 * Throws with `.status` on non-OK so callers can distinguish:
25	 *   - 4xx (Bearer rejected — `profileEnrichmentFailed = "auth"`): the backend
26	 *     doesn't trust our access_token, so future Bearer calls will also 401
27	 *     until the wiring is fixed.
28	 *   - 5xx / network (transient): the session IS valid; we should keep the
29	 *     id_token-only user rather than visually-logging the user out.
30	 *   - 2xx: return the parsed AuthenticatedUserDTO, or null on Zod mismatch.
31	 *
32	 * Also decodes and logs the JWT payload (`iss`/`aud`/`exp`/`sub`) so a
33	 * future log capture reveals the audience/issuer mismatch that causes
34	 * the auth-rejection regression without redacting PII (email/name/picture
35	 * are stripped before logging).
36	 */
37	export async function getAuthenticatedUserExternal(
38	  accessToken: string
39	): Promise<AuthenticatedUserDTO | null> {
40	  if (!accessToken) return null;
41	  if (!isApiUrlConfigured()) return null;
42	  const apiUrl = getApiUrl();
43	
44	  // Decode the access_token payload (no signature verification — that's the
45	  // backend's job) and log iss/aud/exp/sub so a future ``getAuthenticatedUserExternal``
46	  // crash dump exposes the audience/issuer that the backend probably
47	  // doesn't trust. Email/name/picture claims are stripped before logging.
48	  const safeClaims = decodeSafeJwtClaims(accessToken);
49	
50	  try {
51	    const response = await fetchWithHmac(`${apiUrl}/auth/me`, {
52	      headers: { Authorization: `Bearer ${accessToken}` },
53	    });
54	    if (!response.ok) {
55	      const body = await response.text().catch(() => "<unreadable>");
56	      // 2026-07-26 round-10 (mirror of createEvent / uploadEventImage): surface
57	      // the WWW-Authenticate header so Spring's resource-server rejection
58	      // reason (RFC 6750) is one-grep root-caused across all entry points.
59	      // A bare `Bearer resource_metadata="..."` (no `error="..."` directive)
60	      // indicates Spring didn't even attempt JWT decode — same shape as the
61	      // shell-curl-with-no-Authorization response, which strongly suggests the
62	      // request never reached the resource-server's bearer-token filter.
63	      console.error(
64	        `getAuthenticatedUserExternal: HTTP ${response.status} \u2014 body=${body.slice(0, 200)} \u2014 www-authenticate=${response.headers.get("www-authenticate") ?? "<none>"} \u2014 access_token=${safeClaims}`,
65	      );
66	      const err = Object.assign(
67	        new Error(
68	          `getAuthenticatedUserExternal: HTTP ${response.status}`,
69	        ),
70	        { status: response.status },
71	      );
72	      throw err;
73	    }
74	    return parseAuthenticatedUser(await response.json());
75	  } catch (error) {
76	    if ((error as { status?: number })?.status) throw error;
77	    console.error(
78	      `getAuthenticatedUserExternal: failed (network/parse) \u2014 access_token=${safeClaims}`,
79	      error,
80	    );
81	    return null;
82	  }
83	}
