85	/**
86	 * Decode the JWT payload of an access_token without verifying the signature.
87	 * Returns a redacted summary suitable for inclusion in server logs:
88	 * `{iss, aud, exp, scope, sub}` — email/name/picture claims are stripped
89	 * because the production code has them elsewhere (AuthProvider) and a
90	 * redacted summary is enough to diagnose `aud`/`iss`/`exp`/`scope` mismatches.
91	 *
92	 * `scope` is included (capped at 200 chars) because Logto issues the
93	 * granted-permissions list as a space-separated string. Without it, the
94	 * 2026-07-26 silent "GET /api/auth/me works, POST /api/events 401" pattern
95	 * is indistinguishable between "wrong audience" and "missing resource
96	 * scope" — the two are different fixes (one is a JWKS/aud config, the other
97	 * is `LOGTO_API_SCOPES` not set). The string is not PII — it's the same
98	 * scope list the `scope=` query parameter carries in the OAuth flow.
99	 */
100	export function decodeSafeJwtClaims(accessToken: string): string {
101	  try {
102	    const parts = accessToken.split(".");
103	    if (parts.length < 2) return "<unparseable-short-token>";
104	    const padded = parts[1]
105	      .replace(/-/g, "+")
106	      .replace(/_/g, "/")
107	      .padEnd(parts[1].length + ((4 - (parts[1].length % 4)) % 4), "=");
108	    const raw = Buffer.from(padded, "base64").toString("utf-8");
109	    const parsed = JSON.parse(raw) as Record<string, unknown>;
110	    // Logto's `scope` is a space-separated string per RFC 6749 §3.3. Cap to
111	    // 200 chars so a misconfigured tenant with thousands of scopes can't
112	    // bloat log lines; the cap is well above any plausible real scope set.
113	    const rawScope = typeof parsed.scope === "string" ? parsed.scope : undefined;
114	    const summary: Record<string, unknown> = {
115	      iss: parsed.iss,
116	      aud: parsed.aud,
117	      exp: parsed.exp,
118	      scope: rawScope ? rawScope.slice(0, 200) : undefined,
119	      sub: typeof parsed.sub === "string" ? parsed.sub.slice(0, 24) : undefined,
120	    };
121	    return JSON.stringify(summary);
122	  } catch {
123	    return "<unparseable-jwt>";
124	  }
125	}
