796	/**
797	 * Publishing creates a user-attributed event (the backend returns 401 for
798	 * guests). Gate upfront so guests never fill the form only to fail at submit
799	 * — and, by mounting PublishForm only when authenticated, its region/city
800	 * and category data hooks never fire for guests either. A light skeleton
801	 * holds while the session resolves so an authenticated user never sees the
802	 * gate flash.
803	 */
804	const Publica = () => {
805	  const { isAuthenticated, isLoading } = useAuth();
806	
807	  if (isLoading) {
808	    return (
809	      <div className="container flex-center pt-[6rem] pb-section-y">
810	        <div className="w-full max-w-md h-80 rounded-lg bg-border/40 animate-pulse" />
811	      </div>
812	    );
813	  }
814	
815	  if (!isAuthenticated) {
816	    return <PublishAuthGate />;
817	  }
818	
819	  return <PublishForm />;
820	};
