5	/**
6	 * Sanitizes error messages before logging to prevent information disclosure.
7	 * Extracts a safe string representation from unknown error types.
8	 *
9	 * @param error - The error to sanitize (Error, string, or unknown)
10	 * @returns A safe error message string
11	 */
12	export function getSanitizedErrorMessage(error: unknown): string {
13	  if (error instanceof Error) {
14	    return error.message;
15	  }
16	  if (typeof error === "string") {
17	    return error;
18	  }
19	  return "Unknown error";
20	}
21	
22	/**
23	 * Shared error handler for API routes that:
24	 * 1. Captures exceptions to Sentry (production only)
25	 * 2. Logs errors using Sentry logger (when available) or console
26	 * 3. Returns a standardized error response
27	 *
28	 * @param error - The error that occurred
29	 * @param routePath - The API route path for context (e.g., "/api/events")
30	 * @param options - Optional configuration for error response
31	 * @returns NextResponse with appropriate error status and body
32	 */
33	export function handleApiError(
34	  error: unknown,
35	  routePath: string,
36	  options: ApiErrorOptions = {}
37	): NextResponse {
38	  const rawStatus = error instanceof Error && "status" in error
39	    ? (error as Error & { status: unknown }).status
40	    : undefined;
41	  const errorStatus = typeof rawStatus === "number" && rawStatus >= 400 && rawStatus < 600
42	    ? rawStatus
43	    : undefined;
44	  const { status = errorStatus ?? 500, errorMessage, fallbackData, sentryContext } = options;
45	
46	  // Normalize error to Error object for better logging
47	  // Use getSanitizedErrorMessage for consistency with other error handling
48	  const errorObj =
49	    error instanceof Error ? error : new Error(getSanitizedErrorMessage(error));
50	
51	  // Log to console - consoleLoggingIntegration will automatically send to Sentry in production
52	  // when enableLogs: true is set in config. This is the recommended approach for v10.27.0+
53	  console.error(`${routePath} error:`, errorObj);
54	
55	  // Capture exception to Sentry in production
56	  if (process.env.NODE_ENV === "production") {
57	    Sentry.captureException(errorObj, {
58	      tags: {
59	        route: routePath,
60	        ...sentryContext?.tags,
61	      },
62	      extra: {
63	        routePath,
64	        ...sentryContext?.extra,
65	      },
66	    });
67	  }
68	
69	  // Determine response body
70	  let responseBody: unknown;
71	  if (fallbackData !== undefined) {
72	    // Use provided fallback data (e.g., empty array, empty object)
73	    responseBody = fallbackData;
74	  } else if (errorMessage) {
75	    // Use provided error message
76	    responseBody = { error: errorMessage };
77	  } else {
78	    // Default: generic error message
79	    responseBody = { error: "Internal server error" };
80	  }
81	
82	  return NextResponse.json(responseBody, { status });
83	}
