152	/**
153	 * Patch the signed-in user's profile (username/displayName/bio).
154	 * Returns the updated ProfileUpdateResponseDTO. Backend returns 409 (taken)
155	 * for collision, 400 for validation — we surface the real status via re-throw
156	 * so the route handler can map it correctly without going through Zod parse.
157	 */
158	export async function patchMeProfileExternal(
159	  body: ProfileUpdateRequestDTO,
160	  accessToken: string,
161	): Promise<ProfileUpdateResponseDTO | null> {
162	  if (!accessToken || !isApiUrlConfigured()) return null;
163	  const apiUrl = getApiUrl();
164	
165	  try {
166	    const response = await fetchWithHmac(`${apiUrl}/users/me/profile`, {
167	      method: "PATCH",
168	      headers: {
169	        Accept: "application/json",
170	        "Content-Type": "application/json",
171	        Authorization: `Bearer ${accessToken}`,
172	      },
173	      body: JSON.stringify(body),
174	      skipBodySigning: true,
175	    });
176	    if (!response.ok) {
177	      const text = await response.text().catch(() => "");
178	      // Keep the real status so callers can distinguish 409 (taken) from
179	      // validation (400) and auth (403). The route handler maps to the
180	      // user-visible status without going through Zod parse.
