import { NextResponse } from "next/server";
import { createEvent } from "@lib/api/events";

// TEMPORARY debug route — verifies the real createEvent() code path
// (same one app/[locale]/publica/actions.ts's createEventAction calls)
// against the live preprod backend, bypassing the EventForm wizard UI for a
// quick manual QA check. Deleted immediately after use, never committed.
export async function POST() {
  try {
    const event = await createEvent({
      title: "QA agent-browser debug-route test",
      type: "FREE",
      url: "",
      description: "Temporary verification of the createEvent code path.",
      imageUrl: "https://res.cloudinary.com/drigo1xqe/image/upload/v1785150757/avatars/e10c6a5f-306c-487f-9e71-876f67c7bbb2.webp",
      regionId: 22,
      cityId: 25,
      startDate: "2026-08-15",
      startTime: "10:00",
      endDate: "2026-08-15",
      endTime: "12:00",
      location: "Carrer de prova, Aguilar de Segarra",
      categories: [1],
    });
    return NextResponse.json({ ok: true, event });
  } catch (e) {
    const status = (e as { status?: number })?.status;
    const message = e instanceof Error ? e.message : String(e);
    return NextResponse.json({ ok: false, status, message }, { status: 500 });
  }
}

