11	// GET /api/events/[slug] - server-only proxy with server-side HMAC and stable caching
12	export async function GET(
13	  _request: Request,
14	  context: { params: Promise<{ slug: string }> }
15	) {
16	  try {
17	    const { slug } = await context.params;
18	    const data = await eventDetailCache(slug, async (key) => {
