20	    });
21	    return NextResponse.json(data ?? null, {
22	      status: data ? 200 : 404,
23	      headers: {
24	        "Cache-Control": "public, s-maxage=1800, stale-while-revalidate=1800",
25	      },
26	    });
27	  } catch (e) {
28	    return handleApiError(e, "/api/events/[slug]", {
29	      fallbackData: null,
30	    });
31	  }
32	}
