32	  const refreshToken = readTokenFromRequest(request, REFRESH_TOKEN_COOKIE);
33	  const accessToken = readTokenFromRequest(request, ACCESS_TOKEN_COOKIE);
34	
35	  const unauthorized = (): Response => {
36	    const response = NextResponse.json(
37	      { user: null },
38	      { status: 401, headers: NO_STORE },
