46	    // them so the client isn't stuck resending broken cookies.
47	    const hasRawCookie =
48	      request.cookies.has(ID_TOKEN_COOKIE) ||
49	      request.cookies.has(ACCESS_TOKEN_COOKIE) ||
50	      request.cookies.has(REFRESH_TOKEN_COOKIE);
