94	    }
95	
96	    // Refresh → new tokens (incl. a fresh id_token) → derive the user from it.
97	    const refreshed = await refreshAccessToken(config, refreshToken);
98	    if (!refreshed.id_token) {
99	      if (user) return NextResponse.json({ user }, { status: 200, headers: NO_STORE });
