102	    const claims = await verifyStoredIdToken(config, refreshed.id_token);
103	    // Use the freshly refreshed access token, not the (possibly stale) cookie.
104	    const refreshedUser = await enrichWithBackendProfile(
105	      mapClaimsToAuthUser(claims),
106	      refreshed.access_token,
107	    );
108	    const response = NextResponse.json(
109	      { user: refreshedUser },
110	      { status: 200, headers: NO_STORE },
111	    );
112	    setTokenCookies(response, refreshed);
