114	  } catch (e) {
115	    const status = (e as { status?: number })?.status;
116	    // Definitive auth failure (e.g. refresh token revoked/expired). Only log
117	    // out if we never had a valid id_token-derived session to fall back on.
118	    if (status === 400 || status === 401 || status === 403) {
119	      if (user) return NextResponse.json({ user }, { status: 200, headers: NO_STORE });
120	      return unauthorized();
121	    }
122	    // Transient (5xx, network, timeout): keep the session, signal retry.
123	    console.error("[/api/auth/me] transient session check failure", e);
124	    return NextResponse.json({ user: null }, { status: 503, headers: NO_STORE });
125	  }
126	}
