17	// Hydrates the session from the HttpOnly cookie via /api/auth/me, then exposes
18	// redirect-based sign-in / logout. Tokens live in cookies, never in JS.
19	export function AuthProvider({ children }: { children: ReactNode }) {
20	  const [user, setUser] = useState<AuthUser | null>(null);
21	  const [hydrated, setHydrated] = useState(false);
22	
23	  // Fetches /api/auth/me once and resolves `next(user | null)`. Shared by the
24	  // mount-time hydration effect and `refetchUser()` (called after a profile/
25	  // avatar PATCH so `profileCompleted`/`username`/`avatarUrl` update without a
26	  // full page reload — `user` here lives only in this provider's state, so
27	  // nothing else re-fetches it on our behalf).
28	  const load = useCallback(
29	    async (
30	      next: (user: AuthUser | null) => void,
31	      signal: AbortSignal,
32	    ): Promise<void> => {
33	      let retryTimer: ReturnType<typeof setTimeout> | undefined;
34	      let resolveRetry: ((retry: boolean) => void) | undefined;
35	      // /api/auth/me returns 503 on a transient Logto outage while preserving
36	      // the session cookies. Retry once before resolving to unauthenticated
37	      // so a brief blip doesn't flip the UI to logged-out.
38	      const waitBeforeRetry = () =>
39	        new Promise<boolean>((resolve) => {
40	          resolveRetry = resolve;
41	          retryTimer = setTimeout(() => resolve(!signal.aborted), 1500);
42	        });
43	      const cleanupRetry = () => {
44	        if (retryTimer) clearTimeout(retryTimer);
45	        resolveRetry?.(false);
46	      };
47	      signal.addEventListener("abort", cleanupRetry);
48	
49	      try {
50	        for (let attempt = 0; attempt < 2; attempt++) {
51	          try {
52	            const res = await fetch("/api/auth/me", {
53	              credentials: "include",
54	              signal,
55	            });
56	            // 503 = transient Logto outage (cookies preserved server-side).
57	            if (res.status === 503 && attempt === 0) {
58	              if (await waitBeforeRetry()) continue;
59	              next(null);
60	              return;
61	            }
62	            const data = res.ok ? await res.json() : null;
63	            next((data?.user as AuthUser | null) ?? null);
64	            return;
65	          } catch {
66	            // Network blip / offline: retry once before giving up, but never
67	            // after an abort (timeout or unmount).
68	            if (attempt === 0 && !signal.aborted) {
69	              if (await waitBeforeRetry()) continue;
70	            }
71	            next(null);
72	            return;
73	          }
74	        }
75	        next(null);
76	      } finally {
77	        signal.removeEventListener("abort", cleanupRetry);
78	      }
79	    },
80	    [],
81	  );
82	
83	  useEffect(() => {
84	    const controller = new AbortController();
85	    let settled = false;
86	    // `settled` is set on unmount so we never setState after unmount; a timeout
87	    // abort still resolves to unauthenticated (settled is false), so a hanging
88	    // /me can't trap the UI in the loading state.
89	    const finish = (next: AuthUser | null) => {
90	      if (settled) return;
91	      settled = true;
92	      clearTimeout(timeout);
93	      setUser(next);
94	      setHydrated(true);
95	    };
96	    const timeout = setTimeout(() => controller.abort(), 10_000);
97	    void load(finish, controller.signal);
98	    return () => {
99	      settled = true;
100	      clearTimeout(timeout);
101	      controller.abort();
102	    };
103	  }, [load]);
104	
105	  // Re-fetches /api/auth/me and replaces `user` with the result. No retry-503
106	  // handling needed here (that's for the initial hydration race with a
107	  // transient Logto outage) — a plain single attempt is enough for an
108	  // on-demand refresh triggered right after a successful mutation.
109	  const refetchUser = useCallback(async (): Promise<void> => {
110	    const controller = new AbortController();
111	    await load((next) => setUser(next), controller.signal);
112	  }, [load]);
113	
114	  const signIn = useCallback((redirectTo?: string) => {
115	    const query = redirectTo
116	      ? `?redirect=${encodeURIComponent(redirectTo)}`
117	      : "";
118	    window.location.assign(`/api/auth/sign-in${query}`);
119	  }, []);
120	
121	  const logout = useCallback(() => {
122	    window.location.assign("/api/auth/sign-out");
123	  }, []);
124	
125	  const status = !hydrated
126	    ? ("loading" as const)
127	    : user
128	      ? ("authenticated" as const)
129	      : ("unauthenticated" as const);
130	
131	  const value = useMemo<AuthContextValue>(
132	    () => ({
133	      status,
134	      user,
135	      isAuthenticated: status === "authenticated",
136	      isLoading: status === "loading",
137	      signIn,
138	      logout,
139	      refetchUser,
140	    }),
141	    [status, user, signIn, logout, refetchUser],
142	  );
143	
144	  return <AuthContext.Provider value={value}>{children}</AuthContext.Provider>;
145	}
