// an already-onboarded user too, and that must fall through to the
// normal profile link, not the onboarding form.
const profileHref: Href | null =
  user?.profileCompleted === false
    ? "/perfil/edita"
    : profileSlug
      ? `/perfil/${encodeURIComponent(profileSlug)}`
      : null;

