1	"use client";
2	
3	import { useRef, useState } from "react";
4	import { useTranslations } from "next-intl";
5	import { useAuth } from "@components/hooks/useAuth";
6	import type { EditProfileAvatarProps } from "types/props";
7	
8	// Mirrors the caps enforced server-side in app/api/users/me/avatar/route.ts.
9	// Checking here is UX only (fail before the upload round-trip) — the route
10	// is the real gate.
11	const MAX_AVATAR_BYTES = 2 * 1024 * 1024;
12	const ALLOWED_AVATAR_TYPES = new Set([
13	  "image/jpeg",
14	  "image/png",
15	  "image/jpg",
16	  "image/webp",
17	]);
18	
19	function AvatarFallback({ name }: { name: string }) {
20	  const initial = (name.trim().charAt(0) || "?").toUpperCase();
21	  return (
22	    <div
23	      className="w-20 h-20 rounded-full bg-primary text-white flex items-center justify-center text-3xl font-bold"
24	      role="img"
25	      aria-label={name}
26	    >
27	      {initial}
28	    </div>
29	  );
30	}
31	
32	export default function EditProfileAvatar({
33	  className,
34	}: EditProfileAvatarProps) {
35	  const t = useTranslations("App.EditProfile.avatar");
36	  const { user, refetchUser } = useAuth();
37	  const fileInputRef = useRef<HTMLInputElement>(null);
38	  const [isUploading, setIsUploading] = useState(false);
39	  const [isRemoving, setIsRemoving] = useState(false);
40	  const [error, setError] = useState<string | null>(null);
41	
42	  const displayName = user?.name || user?.username || "";
43	  const avatarUrl = user?.avatarUrl;
44	  const busy = isUploading || isRemoving;
45	
46	  const handleSelectClick = () => {
47	    setError(null);
48	    fileInputRef.current?.click();
49	  };
50	
51	  const handleFileChange = async (
52	    event: React.ChangeEvent<HTMLInputElement>,
53	  ): Promise<void> => {
54	    const file = event.target.files?.[0];
55	    event.target.value = ""; // allow re-selecting the same file later
56	    if (!file) return;
57	
58	    setError(null);
59	
60	    if (!ALLOWED_AVATAR_TYPES.has(file.type)) {
61	      setError(t("errorUnsupported"));
62	      return;
63	    }
64	    if (file.size > MAX_AVATAR_BYTES) {
65	      setError(t("errorTooLarge"));
66	      return;
67	    }
68	
69	    setIsUploading(true);
70	    try {
71	      const formData = new FormData();
72	      formData.append("avatarFile", file);
73	      const response = await fetch("/api/users/me/avatar", {
74	        method: "POST",
75	        credentials: "include",
76	        body: formData,
77	      });
78	      if (!response.ok) {
79	        setError(t("errorUploadFailed"));
80	        return;
81	      }
82	      await refetchUser();
83	    } catch {
84	      setError(t("errorUploadFailed"));
85	    } finally {
86	      setIsUploading(false);
87	    }
88	  };
89	
90	  const handleRemove = async (): Promise<void> => {
91	    setError(null);
92	    setIsRemoving(true);
93	    try {
94	      const response = await fetch("/api/users/me/avatar", {
95	        method: "DELETE",
96	        credentials: "include",
97	      });
98	      if (!response.ok) {
99	        setError(t("errorRemoveFailed"));
100	        return;
101	      }
102	      await refetchUser();
103	    } catch {
104	      setError(t("errorRemoveFailed"));
105	    } finally {
106	      setIsRemoving(false);
107	    }
108	  };
109	
110	  return (
111	    <div className={`w-full ${className ?? ""}`}>
112	      <label className="form-label">{t("label")}</label>
113	      <div className="mt-2 flex items-center gap-element-gap">
114	        {avatarUrl ? (
115	          // eslint-disable-next-line @next/next/no-img-element -- user-uploaded, not eligible for static optimization
116	          <img
117	            src={avatarUrl}
118	            alt={t("altPreview")}
119	            className="w-20 h-20 rounded-full object-cover"
120	          />
121	        ) : (
122	          <AvatarFallback name={displayName} />
123	        )}
124	        <div className="flex flex-col gap-2">
125	          <button
126	            type="button"
127	            className="btn-outline btn-sm"
128	            onClick={handleSelectClick}
129	            disabled={busy}
130	          >
131	            {isUploading ? t("uploading") : t("uploadButton")}
132	          </button>
133	          {avatarUrl && (
134	            <button
135	              type="button"
136	              className="btn-outline btn-sm"
137	              onClick={() => {
138	                void handleRemove();
139	              }}
140	              disabled={busy}
141	            >
142	              {isRemoving ? t("removing") : t("removeButton")}
143	            </button>
144	          )}
145	        </div>
146	        <input
147	          ref={fileInputRef}
148	          type="file"
149	          accept="image/png, image/jpeg, image/jpg, image/webp"
150	          className="hidden"
151	          onChange={(event) => {
152	            void handleFileChange(event);
153	          }}
154	        />
155	      </div>
156	      {error && (
157	        <p className="helper-text-error mt-2" role="alert">
158	          {error}
159	        </p>
160	      )}
161	    </div>
162	  );
163	}
