2	import { render, screen, fireEvent, waitFor } from "@testing-library/react";
3	import type { AuthUser } from "types/auth";
4	
5	const baseUser: AuthUser = {
6	  id: "user-1",
7	  email: "alex@example.com",
8	  name: "Alex Garcia",
9	  username: "alex91",
10	  avatarUrl: undefined,
11	};
12	
13	let authUser: AuthUser = baseUser;
14	const mockRefetchUser = vi.fn();
15	
16	vi.mock("next-intl", () => ({
