22	}));
23	
24	import EditProfileAvatar from "@app/[locale]/perfil/edita/EditProfileAvatar";
25	
26	function makeFile(name: string, type: string, sizeBytes: number): File {
27	  const file = new File([new Uint8Array(sizeBytes)], name, { type });
28	  return file;
29	}
30	
31	describe("EditProfileAvatar", () => {
32	  beforeEach(() => {
33	    authUser = baseUser;
34	    mockRefetchUser.mockReset().mockResolvedValue(undefined);
35	    vi.stubGlobal("fetch", vi.fn());
36	  });
37	
38	  it("shows the initial-letter fallback when there is no avatarUrl", () => {
39	    render(<EditProfileAvatar />);
40	    expect(screen.getByRole("img", { name: "Alex Garcia" })).toBeInTheDocument();
41	    expect(screen.queryByText("removeButton")).toBeNull();
42	  });
43	
44	  it("shows a remove button once an avatarUrl is set", () => {
45	    authUser = { ...baseUser, avatarUrl: "https://cdn.example.com/a.jpg" };
46	    render(<EditProfileAvatar />);
47	    expect(screen.getByText("removeButton")).toBeInTheDocument();
48	  });
49	
50	  it("rejects an unsupported file type locally, without uploading", async () => {
51	    render(<EditProfileAvatar />);
52	    const input = document.querySelector('input[type="file"]') as HTMLInputElement;
53	    const file = makeFile("avatar.gif", "image/gif", 1024);
54	    fireEvent.change(input, { target: { files: [file] } });
55	
56	    expect(await screen.findByText("errorUnsupported")).toBeInTheDocument();
57	    expect(fetch).not.toHaveBeenCalled();
58	  });
59	
60	  it("rejects an oversized file locally, without uploading", async () => {
61	    render(<EditProfileAvatar />);
62	    const input = document.querySelector('input[type="file"]') as HTMLInputElement;
63	    const file = makeFile("avatar.jpg", "image/jpeg", 3 * 1024 * 1024);
64	    fireEvent.change(input, { target: { files: [file] } });
65	
66	    expect(await screen.findByText("errorTooLarge")).toBeInTheDocument();
67	    expect(fetch).not.toHaveBeenCalled();
68	  });
69	
70	  it("uploads a valid file with the avatarFile field and refetches the session", async () => {
71	    vi.mocked(fetch).mockResolvedValue({
72	      ok: true,
73	      status: 200,
74	      json: () => Promise.resolve({ avatarUrl: "https://cdn.example.com/a.jpg" }),
75	    } as Response);
76	
77	    render(<EditProfileAvatar />);
78	    const input = document.querySelector('input[type="file"]') as HTMLInputElement;
79	    const file = makeFile("avatar.jpg", "image/jpeg", 1024);
80	    fireEvent.change(input, { target: { files: [file] } });
81	
82	    await waitFor(() => expect(mockRefetchUser).toHaveBeenCalledTimes(1));
83	    const [url, init] = vi.mocked(fetch).mock.calls[0];
84	    expect(url).toBe("/api/users/me/avatar");
85	    expect((init as RequestInit).method).toBe("POST");
86	    const body = (init as RequestInit).body as FormData;
87	    expect(body.get("avatarFile")).toBe(file);
88	  });
89	
90	  it("removes the avatar and refetches the session", async () => {
91	    authUser = { ...baseUser, avatarUrl: "https://cdn.example.com/a.jpg" };
92	    vi.mocked(fetch).mockResolvedValue({
93	      ok: true,
94	      status: 200,
95	      json: () => Promise.resolve({ ok: true }),
96	    } as Response);
97	
98	    render(<EditProfileAvatar />);
99	    fireEvent.click(screen.getByText("removeButton"));
100	
101	    await waitFor(() => expect(mockRefetchUser).toHaveBeenCalledTimes(1));
102	    expect(fetch).toHaveBeenCalledWith(
103	      "/api/users/me/avatar",
104	      expect.objectContaining({ method: "DELETE", credentials: "include" }),
105	    );
106	  });
107	
108	  it("surfaces an upload failure without refetching", async () => {
109	    vi.mocked(fetch).mockResolvedValue({
110	      ok: false,
111	      status: 500,
112	      json: () => Promise.resolve(null),
113	    } as Response);
114	
115	    render(<EditProfileAvatar />);
116	    const input = document.querySelector('input[type="file"]') as HTMLInputElement;
117	    const file = makeFile("avatar.jpg", "image/jpeg", 1024);
118	    fireEvent.change(input, { target: { files: [file] } });
119	
120	    expect(await screen.findByText("errorUploadFailed")).toBeInTheDocument();
121	    expect(mockRefetchUser).not.toHaveBeenCalled();
122	  });
123	});
