    aria-invalid={usernameError ? "true" : "false"}
    aria-describedby={
      [
        showUsernameHint && "username-hint",
        usernameLocked && "username-locked-hint",
        usernameError && "username-error",
      ]
        .filter(Boolean)
        .join(" ") || undefined
    }
  />
  {usernameError && (
    <p id="username-error" className="helper-text-error" role="alert">
      {usernameError}
    </p>
  )}

