1	import ProfileOwnerActions from "@components/ui/profile/ProfileOwnerActions";
2	import { getTranslations } from "next-intl/server";
3	import { getLocaleSafely } from "@utils/i18n-seo";
4	import { parseBackendDateAsUtcMs } from "@utils/date-helpers";
5	import type { AppLocale } from "types/i18n";
6	import type { ProfileHeaderProps } from "types/props";
7	
8	function AvatarFallback({ name }: { name: string }) {
9	  const initial = name.charAt(0).toUpperCase();
10	  return (
11	    <div
12	      className="w-20 h-20 rounded-full bg-primary text-white flex items-center justify-center text-3xl font-bold"
13	      role="img"
14	      aria-label={name}
15	    >
16	      {initial}
17	    </div>
18	  );
19	}
20	
21	/** Format a backend ISO date-time as a locale-aware month + year string.
22	 *  Uses parseBackendDateAsUtcMs to handle timezone-naive strings the backend
23	 *  may emit (e.g. "2023-01-15T10:30:00" without a Z suffix). */
24	function formatJoinedDate(isoDate: string, locale: AppLocale): string {
25	  const ms = parseBackendDateAsUtcMs(isoDate);
26	  if (ms === null) return "";
27	  return new Intl.DateTimeFormat(locale, {
28	    month: "long",
29	    year: "numeric",
30	    timeZone: "UTC",
31	  }).format(new Date(ms));
32	}
33	
34	export default async function ProfileHeader({ profile }: ProfileHeaderProps) {
35	  const [t, locale] = await Promise.all([
36	    getTranslations("Components.Profile"),
37	    getLocaleSafely(),
38	  ]);
39	
40	  const joinedDateText = profile.createdAt
41	    ? formatJoinedDate(profile.createdAt, locale)
42	    : "";
43	
44	  // 2026-07-25 backend moved to `displayName`/`avatarUrl`. Legacy fields
45	  // come from older backend instances during the cut-over window.
46	  const displayName =
47	    profile.displayName?.trim() || profile.name?.trim() || profile.username;
48	  const avatarSrc = profile.avatarUrl || profile.pictureUrl;
49	
50	  // Cap runs of blank lines before rendering with whitespace-pre-line: the
51	  // 500-char limit alone doesn't stop a bio that's mostly newlines (e.g.
52	  // "\n" x200 plus a few words), which would otherwise blow up the page
53	  // with empty vertical space for every visitor.
54	  const bioText = profile.bio?.trim().replace(/\n{3,}/g, "\n\n");
55	
56	  return (
57	    <section
58	      className="card-bordered rounded-lg overflow-hidden mb-section-y w-full"
59	      aria-label={t("title", { name: displayName })}
60	      data-testid="profile-header"
61	    >
62	      <div className="px-section-x py-element-gap relative">
63	        <div className="flex items-end gap-element-gap mb-element-gap">
64	          {avatarSrc ? (
65	            // bg-background: a transparent-background upload (e.g. a logo)
66	            // should show against a neutral backdrop, not whatever's behind it.
67	            <img
68	              src={avatarSrc}
69	              alt={displayName}
70	              className="w-20 h-20 rounded-full object-cover bg-background border-4 border-background shadow-md"
71	              loading="eager"
72	            />
73	          ) : (
74	            <AvatarFallback name={displayName} />
75	          )}
76	        </div>
77	
78	        <div className="flex items-center gap-2 mb-2 flex-wrap">
79	          <h1 className="heading-1 text-foreground">{displayName}</h1>
80	          <ProfileOwnerActions username={profile.username} />
81	        </div>
82	
83	        <p className="body-small text-foreground/60 mb-1">@{profile.username}</p>
84	
85	        {bioText && (
86	          <p className="body-normal text-foreground/80 mb-element-gap whitespace-pre-line break-words">
87	            {bioText}
88	          </p>
89	        )}
90	
91	        {joinedDateText && (
92	          <p className="body-small text-foreground/50">
93	            {t("joinedDate", { date: joinedDateText })}
94	          </p>
95	        )}
96	      </div>
97	    </section>
98	  );
99	}
