58	// Wrap in React cache() so multiple server components/actions calling
59	// getCurrentUser() in the same request share a single backend enrichment call
60	// (avoids redundant GET /auth/me round-trips within one request cycle).
61	export const getCurrentUser = cache(getCurrentUserInternal);
