36	export async function getAuthenticatedUserExternal(
37	  accessToken: string
38	): Promise<AuthenticatedUserDTO | null> {
39	  if (!accessToken) return null;
40	  if (!isApiUrlConfigured()) return null;
41	  const apiUrl = getApiUrl();
42	
43	  // Decode the access_token payload (no signature verification — that's the
44	  // backend's job) and log iss/aud/exp/sub so a future ``getAuthenticatedUserExternal``
45	  // crash dump exposes the audience/issuer that the backend probably
46	  // doesn't trust. Email/name/picture claims are stripped before logging.
47	  const safeClaims = decodeSafeJwtClaims(accessToken);
48	
49	  try {
50	    const response = await fetchWithHmac(`${apiUrl}/auth/me`, {
51	      headers: { Authorization: `Bearer ${accessToken}` },
52	    });
53	    if (!response.ok) {
54	      const body = await response.text().catch(() => "<unreadable>");
55	      // 2026-07-26 round-10 (mirror of createEvent / uploadEventImage): surface
56	      // the WWW-Authenticate header so Spring's resource-server rejection
57	      // reason (RFC 6750) is one-grep root-caused across all entry points.
58	      // A bare `Bearer resource_metadata="..."` (no `error="..."` directive)
59	      // indicates Spring didn't even attempt JWT decode — same shape as the
60	      // shell-curl-with-no-Authorization response, which strongly suggests the
61	      // request never reached the resource-server's bearer-token filter.
62	      console.error(
63	        `getAuthenticatedUserExternal: HTTP ${response.status} \u2014 body=${body.slice(0, 200)} \u2014 www-authenticate=${response.headers.get("www-authenticate") ?? "<none>"} \u2014 access_token=${safeClaims}`,
64	      );
65	      const err = Object.assign(
66	        new Error(
67	          `getAuthenticatedUserExternal: HTTP ${response.status}`,
68	        ),
69	        { status: response.status },
70	      );
71	      throw err;
72	    }
73	    return parseAuthenticatedUser(await response.json());
74	  } catch (error) {
75	    if ((error as { status?: number })?.status) throw error;
76	    console.error(
77	      `getAuthenticatedUserExternal: failed (network/parse) \u2014 access_token=${safeClaims}`,
78	      error,
