45	  // (profileCompleted: false per backend spec — user should complete
46	  // onboarding). Anything else is a real 5xx and rethrows. We log + tag
47	  // Sentry with the next action so the form can render the right message.
48	  let created;
49	  try {
50	    // 1. Create the event in your backend
51	    created = await createEvent(data, e2eExtras);
52	  } catch (err) {
53	    const status = (err as { status?: number })?.status;
54	    if (status === 401 || status === 403) {
55	      const nextAction =
56	        status === 401 ? "logout-and-relogin" : "complete-profile";
57	      console.error(
58	        `createEventAction: backend rejected with ${status} \u2014 ${status === 401 ? "Likely stale Bearer \u2014 user should log out and back in." : "Likely profileCompleted: false \u2014 user should complete profile onboarding."}`,
59	      );
60	      captureException(err, {
61	        tags: {
62	          section: "publica-create",
63	          authStatus: String(status),
64	          nextAction,
65	        },
66	        // Send only field names + truncated title to avoid leaking content.
67	        extra: {
68	          dataFields: Object.keys(data ?? {}),
69	          titleHint: data?.title?.slice(0, 40),
70	        },
71	      });
72	    }
73	    throw err;
74	  }
75	
76	  // 2. Send email notification (fire-and-forget, non-blocking)
77	  // Uses `after` to ensure execution completes in serverless environments
78	  if (created?.slug && created?.title) {
79	    const { title, slug } = created;
80	    after(() => sendNewEventEmail(title, slug));
81	  }
